import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";var i=JSON.parse(`{"title":"从购买域名到更换域名","description":"记录一次完整的博客域名更换流程：DNS 解析、站点配置、SEO 收录迁移与常见的坑。","frontmatter":{"title":"从购买域名到更换域名","date":"2026-08-30T00:00:00.000Z","tags":["工程化","博客"],"category":"前端","description":"记录一次完整的博客域名更换流程：DNS 解析、站点配置、SEO 收录迁移与常见的坑。"},"headers":[],"relativePath":"articles/frontEnd/changed-the-domain.md","filePath":"articles/frontEnd/changed-the-domain.md","articleMeta":{"updated":"2026-08-30","words":375,"minutes":1}}`),a={name:`articles/frontEnd/changed-the-domain.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<p>域名是博客的门面。当博客从一个域名迁移到另一个域名时，看似只是改一行配置，实际上涉及 DNS、构建配置、SEO 收录等一系列问题。</p><h2 id="为什么换域名" tabindex="-1">为什么换域名 <a class="header-anchor" href="#为什么换域名" aria-label="Permalink to “为什么换域名”">​</a></h2><ul><li>旧域名续费成本过高</li><li>想统一个人品牌</li><li>旧域名历史解析记录混乱</li></ul><h2 id="更换流程" tabindex="-1">更换流程 <a class="header-anchor" href="#更换流程" aria-label="Permalink to “更换流程”">​</a></h2><ol><li><strong>购买新域名</strong>：选择靠谱的注册商，注意隐私保护选项</li><li><strong>配置 DNS 解析</strong>：将新域名 CNAME 或 A 记录指向部署平台</li><li><strong>更新站点配置</strong>：修改部署平台的自定义域名设置</li><li><strong>设置 301 重定向</strong>：在旧域名上配置永久重定向，保留权重</li><li><strong>提交搜索引擎</strong>：更新 Search Engine Console 中的站点地址</li></ol><h2 id="踩过的坑" tabindex="-1">踩过的坑 <a class="header-anchor" href="#踩过的坑" aria-label="Permalink to “踩过的坑”">​</a></h2><ul><li>CDN 缓存未刷新，导致新旧域名内容不一致</li><li>忘记更新 RSS 地址，订阅读者收到错误</li><li><code>robots.txt</code> 与 sitemap 未同步更新</li></ul><p>总结：换域名不难，难的是&quot;善后&quot;。做好重定向与收录迁移，流量基本无损。</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};